-- ShowDoc PostgreSQL 18 schema
-- Generated from the upgraded SQLite schema.
--
-- Usage:
--   createdb -O showdoc showdoc
--   psql -U showdoc -d showdoc -v ON_ERROR_STOP=1 -f install/showdoc.pgsql.sql
--
-- The application also runs this file automatically on an empty PostgreSQL database
-- from Upgrade::installPgsqlSchema().

BEGIN;

CREATE TABLE IF NOT EXISTS "ai_chat_messages" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "session_id" INTEGER NOT NULL DEFAULT '0',
    "role" VARCHAR(20) NOT NULL DEFAULT 'user',
    "content" TEXT,
    "feedback" SMALLINT NOT NULL DEFAULT '0',
    "created_at" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_ai_message_session" ON "ai_chat_messages" ("session_id", "id");

CREATE TABLE IF NOT EXISTS "ai_chat_sessions" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "guest_token" VARCHAR(64) DEFAULT NULL,
    "last_message_at" INTEGER NOT NULL DEFAULT '0',
    "created_at" INTEGER NOT NULL DEFAULT '0',
    "is_del" SMALLINT NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_ai_session_lastmsg" ON "ai_chat_sessions" ("last_message_at");
CREATE INDEX IF NOT EXISTS "idx_ai_session_guest" ON "ai_chat_sessions" ("guest_token");
CREATE INDEX IF NOT EXISTS "idx_ai_session_uid_item" ON "ai_chat_sessions" ("uid", "item_id");

CREATE TABLE IF NOT EXISTS "captcha" (
    "captcha_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "mobile" VARCHAR(200) NOT NULL DEFAULT '',
    "captcha" VARCHAR(200) NOT NULL DEFAULT '',
    "expire_time" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("captcha_id")
);

CREATE TABLE IF NOT EXISTS "catalog" (
    "cat_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "cat_name" TEXT,
    "item_id" INTEGER,
    "s_number" INTEGER DEFAULT 99,
    "addtime" INTEGER DEFAULT 0,
    "parent_cat_id" INTEGER NOT NULL DEFAULT '0',
    "level" INTEGER NOT NULL DEFAULT '2',
    PRIMARY KEY ("cat_id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_catalog_cat_id" ON "catalog" ("cat_id");

CREATE TABLE IF NOT EXISTS "export_log" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "export_type" VARCHAR(200) NOT NULL DEFAULT '',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "addtime" BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "file_flow" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "used" INTEGER NOT NULL DEFAULT '0',
    "date_month" TEXT NOT NULL DEFAULT '',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "file_page" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "file_id" INTEGER NOT NULL DEFAULT '0',
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "addtime" BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "item" (
    "item_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_name" TEXT,
    "item_description" TEXT,
    "uid" INTEGER,
    "username" TEXT,
    "password" TEXT,
    "addtime" INTEGER,
    "last_update_time" INTEGER DEFAULT 0,
    "item_domain" VARCHAR(255) NOT NULL DEFAULT '',
    "item_type" INTEGER NOT NULL DEFAULT '1',
    "is_archived" INTEGER NOT NULL DEFAULT '0',
    "is_del" INTEGER NOT NULL DEFAULT '0',
    "allow_comment" INTEGER NOT NULL DEFAULT '0',
    "allow_feedback" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("item_id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_item_item_id" ON "item" ("item_id");

CREATE TABLE IF NOT EXISTS "item_ai_config" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "enabled" INTEGER NOT NULL DEFAULT '0',
    "dialog_collapsed" INTEGER NOT NULL DEFAULT '1',
    "welcome_message" TEXT NOT NULL DEFAULT '',
    "system_prompt" TEXT NOT NULL DEFAULT '',
    "guest_enabled" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "updatetime" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_enabled" ON "item_ai_config" ("enabled");
CREATE UNIQUE INDEX IF NOT EXISTS "uk_item_id" ON "item_ai_config" ("item_id");

CREATE TABLE IF NOT EXISTS "item_change_log" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "op_action_type" TEXT NOT NULL DEFAULT '',
    "op_object_type" TEXT NOT NULL DEFAULT '',
    "op_object_id" INTEGER NOT NULL DEFAULT '0',
    "op_object_name" TEXT NOT NULL DEFAULT '',
    "remark" TEXT NOT NULL DEFAULT '',
    "optime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "item_group" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "group_name" TEXT NOT NULL DEFAULT '',
    "item_ids" TEXT NOT NULL DEFAULT '',
    "s_number" INTEGER NOT NULL DEFAULT '0',
    "created_at" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "updated_at" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "item_member" (
    "item_member_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" INTEGER,
    "uid" INTEGER,
    "username" TEXT,
    "addtime" INTEGER DEFAULT 0,
    "member_group_id" INTEGER NOT NULL DEFAULT '1',
    "cat_id" INTEGER NOT NULL DEFAULT '0',
    "cat_ids" TEXT NOT NULL DEFAULT '',
    PRIMARY KEY ("item_member_id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_item_member_item_member_id" ON "item_member" ("item_member_id");

CREATE TABLE IF NOT EXISTS "item_sort" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "item_sort_data" TEXT NOT NULL DEFAULT '',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "item_group_id" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "item_star" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "s_number" INTEGER NOT NULL DEFAULT '0',
    "created_at" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "updated_at" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "item_token" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "api_key" VARCHAR(200) NOT NULL,
    "api_token" VARCHAR(200) NOT NULL,
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "last_check_time" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_item_token_api_key" ON "item_token" ("api_key");

CREATE TABLE IF NOT EXISTS "item_top" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "item_variable" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "var_name" TEXT NOT NULL DEFAULT '',
    "var_value" TEXT NOT NULL DEFAULT '',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "env_id" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "kanban_activity_log" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" BIGINT NOT NULL DEFAULT '0',
    "page_id" BIGINT NOT NULL DEFAULT '0',
    "event_type" VARCHAR(32) NOT NULL DEFAULT '',
    "event_data" TEXT,
    "operator_uid" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_kanban_activity_addtime" ON "kanban_activity_log" ("addtime");
CREATE INDEX IF NOT EXISTS "idx_kanban_activity_item" ON "kanban_activity_log" ("item_id");

CREATE TABLE IF NOT EXISTS "message" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "from_uid" INTEGER NOT NULL DEFAULT '0',
    "to_uid" INTEGER NOT NULL DEFAULT '0',
    "message_type" TEXT NOT NULL DEFAULT '',
    "message_content_id" INTEGER NOT NULL DEFAULT '0',
    "status" INTEGER NOT NULL DEFAULT '0',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "readtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "message_content" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "from_uid" INTEGER NOT NULL DEFAULT '0',
    "from_name" TEXT NOT NULL DEFAULT '',
    "message_type" TEXT NOT NULL DEFAULT '',
    "message_content" TEXT NOT NULL DEFAULT '',
    "action_type" TEXT NOT NULL DEFAULT '',
    "object_type" TEXT NOT NULL DEFAULT '',
    "object_id" INTEGER NOT NULL DEFAULT '0',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "mock" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "unique_key" TEXT NOT NULL DEFAULT '',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "view_times" INTEGER NOT NULL DEFAULT '0',
    "template" TEXT NOT NULL DEFAULT '',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "last_update_time" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "path" TEXT NOT NULL DEFAULT '',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "options" (
    "option_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "option_name" VARCHAR(200) NOT NULL,
    "option_value" TEXT NOT NULL,
    PRIMARY KEY ("option_id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_options_option_name" ON "options" ("option_name");

CREATE TABLE IF NOT EXISTS "page" (
    "page_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "author_uid" INTEGER,
    "author_username" TEXT,
    "item_id" INTEGER,
    "cat_id" INTEGER,
    "page_title" TEXT,
    "page_content" TEXT,
    "s_number" INTEGER DEFAULT 99,
    "addtime" INTEGER DEFAULT 0,
    "page_comments" TEXT NOT NULL DEFAULT '',
    "is_del" INTEGER NOT NULL DEFAULT '0',
    "page_addtime" INTEGER NOT NULL DEFAULT '0',
    "ext_info" TEXT NOT NULL DEFAULT '',
    "is_draft" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("page_id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_page_page_id" ON "page" ("page_id");

CREATE TABLE IF NOT EXISTS "page_comment" (
    "comment_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "parent_id" INTEGER NOT NULL DEFAULT '0',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "username" VARCHAR(200) NOT NULL DEFAULT '',
    "content" TEXT NOT NULL DEFAULT '',
    "is_deleted" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("comment_id")
);

CREATE TABLE IF NOT EXISTS "page_feedback" (
    "feedback_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "client_id" VARCHAR(200) DEFAULT NULL,
    "feedback_type" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("feedback_id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "unique_client_feedback" ON "page_feedback" ("page_id", "client_id");
CREATE UNIQUE INDEX IF NOT EXISTS "unique_user_feedback" ON "page_feedback" ("page_id", "uid");

CREATE TABLE IF NOT EXISTS "page_history" (
    "page_history_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "page_id" INTEGER,
    "author_uid" INTEGER,
    "author_username" TEXT,
    "item_id" INTEGER,
    "cat_id" INTEGER,
    "page_title" TEXT,
    "page_content" TEXT,
    "s_number" INTEGER,
    "addtime" INTEGER,
    "page_comments" TEXT NOT NULL DEFAULT '',
    "ext_info" TEXT NOT NULL DEFAULT '',
    PRIMARY KEY ("page_history_id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_page_history_page_history_id" ON "page_history" ("page_history_id");

CREATE TABLE IF NOT EXISTS "page_lock" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "lock_uid" INTEGER NOT NULL DEFAULT '0',
    "lock_username" VARCHAR(200) NOT NULL DEFAULT '',
    "lock_to" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "parameter_description_entry" (
    "id" TEXT,
    "item_id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "type" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "example" TEXT,
    "default_value" TEXT,
    "aliases" TEXT,
    "tags" TEXT,
    "path" TEXT,
    "source" TEXT NOT NULL DEFAULT 'manual',
    "status" TEXT NOT NULL DEFAULT 'permanent',
    "usage_count" INTEGER NOT NULL DEFAULT 0,
    "quality_score" NUMERIC NOT NULL DEFAULT 0.00,
    "created_by" TEXT NOT NULL,
    "created_at" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_updated_at" ON "parameter_description_entry" ("updated_at");
CREATE INDEX IF NOT EXISTS "idx_created_at" ON "parameter_description_entry" ("created_at");
CREATE INDEX IF NOT EXISTS "idx_status" ON "parameter_description_entry" ("status");
CREATE INDEX IF NOT EXISTS "idx_type" ON "parameter_description_entry" ("type");
CREATE INDEX IF NOT EXISTS "idx_name" ON "parameter_description_entry" ("name");
CREATE INDEX IF NOT EXISTS "idx_item_id" ON "parameter_description_entry" ("item_id");
CREATE UNIQUE INDEX IF NOT EXISTS "uk_item_name_type" ON "parameter_description_entry" ("item_id", "name", "type");

CREATE TABLE IF NOT EXISTS "recycle" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "page_title" VARCHAR(200) NOT NULL DEFAULT '',
    "del_by_uid" INTEGER NOT NULL DEFAULT '0',
    "del_by_username" VARCHAR(200) NOT NULL DEFAULT '',
    "del_time" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "runapi_db_config" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "env_id" INTEGER NOT NULL DEFAULT '0',
    "config_name" VARCHAR(100) NOT NULL DEFAULT '默认',
    "db_type" VARCHAR(20) NOT NULL DEFAULT 'mysql',
    "host" VARCHAR(255) NOT NULL DEFAULT '',
    "port" INTEGER NOT NULL DEFAULT '0',
    "username" VARCHAR(255) NOT NULL DEFAULT '',
    "password" VARCHAR(255) NOT NULL DEFAULT '',
    "database" VARCHAR(255) NOT NULL DEFAULT '',
    "options" TEXT NOT NULL DEFAULT '',
    "is_default" INTEGER NOT NULL DEFAULT '0',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "last_update_time" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "uid" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "uniq_item_env_name" ON "runapi_db_config" ("item_id", "env_id", "config_name");

CREATE TABLE IF NOT EXISTS "runapi_env" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "env_name" TEXT NOT NULL DEFAULT '',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "last_update_time" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "runapi_env_selectd" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "env_id" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "runapi_flow" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "flow_name" TEXT NOT NULL DEFAULT '',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "username" TEXT NOT NULL DEFAULT '',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "env_id" INTEGER NOT NULL DEFAULT '0',
    "times" INTEGER NOT NULL DEFAULT '0',
    "time_interval" INTEGER NOT NULL DEFAULT '0',
    "error_continue" INTEGER NOT NULL DEFAULT '0',
    "save_change" INTEGER NOT NULL DEFAULT '0',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "last_update_time" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "runapi_flow_page" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "flow_id" INTEGER NOT NULL DEFAULT '0',
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "s_number" INTEGER NOT NULL DEFAULT '0',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "enabled" INTEGER NOT NULL DEFAULT '1',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "runapi_global_param" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "param_type" TEXT NOT NULL DEFAULT '',
    "content_json_str" TEXT NOT NULL DEFAULT '',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    "last_update_time" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "single_page" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "unique_key" VARCHAR(200) NOT NULL DEFAULT '',
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "expire_time" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "subscription" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "object_id" INTEGER NOT NULL DEFAULT '0',
    "object_type" TEXT NOT NULL DEFAULT '',
    "action_type" TEXT NOT NULL DEFAULT '',
    "sub_time" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "team" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "team_name" VARCHAR(200) NOT NULL DEFAULT '',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "username" VARCHAR(200) NOT NULL DEFAULT '',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "last_update_time" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "team_item" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "team_id" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "last_update_time" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "team_item_member" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "team_id" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "member_group_id" INTEGER NOT NULL DEFAULT '0',
    "member_uid" INTEGER NOT NULL DEFAULT '0',
    "member_username" VARCHAR(200) NOT NULL DEFAULT '',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "last_update_time" INTEGER NOT NULL DEFAULT '0',
    "cat_id" INTEGER NOT NULL DEFAULT '0',
    "cat_ids" TEXT NOT NULL DEFAULT '',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "team_member" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "team_id" INTEGER NOT NULL DEFAULT '0',
    "member_uid" INTEGER NOT NULL DEFAULT '0',
    "member_username" VARCHAR(200) NOT NULL DEFAULT '',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "last_update_time" INTEGER NOT NULL DEFAULT '0',
    "team_member_group_id" INTEGER NOT NULL DEFAULT '1',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "template" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "username" VARCHAR(200) NOT NULL DEFAULT '',
    "template_title" VARCHAR(200) NOT NULL DEFAULT '',
    "template_content" TEXT NOT NULL DEFAULT '',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "template_item" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "template_id" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "uid" INTEGER NOT NULL DEFAULT '0',
    "username" TEXT NOT NULL DEFAULT '',
    "created_at" TEXT NOT NULL DEFAULT '',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "upload_file" (
    "file_id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "sign" VARCHAR(200) NOT NULL DEFAULT '',
    "display_name" VARCHAR(200) NOT NULL DEFAULT '',
    "file_type" VARCHAR(200) NOT NULL DEFAULT '',
    "file_size" BIGINT NOT NULL DEFAULT 0,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "page_id" INTEGER NOT NULL DEFAULT '0',
    "item_id" INTEGER NOT NULL DEFAULT '0',
    "visit_times" INTEGER NOT NULL DEFAULT '0',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    "real_url" VARCHAR(200) NOT NULL DEFAULT '',
    "last_update_time" INTEGER NOT NULL DEFAULT '0',
    "last_visit_time" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("file_id")
);

CREATE TABLE IF NOT EXISTS "user" (
    "uid" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "username" TEXT,
    "groupid" INTEGER DEFAULT 2,
    "name" TEXT,
    "avatar" TEXT,
    "avatar_small" TEXT,
    "email" TEXT,
    "email_verify" SMALLINT NOT NULL DEFAULT '0',
    "mobile" VARCHAR(50) NOT NULL DEFAULT '',
    "mobile_verify" SMALLINT NOT NULL DEFAULT '0',
    "password" TEXT,
    "cookie_token" TEXT,
    "cookie_token_expire" TEXT DEFAULT '0',
    "reg_time" INTEGER DEFAULT 0,
    "last_login_time" INTEGER DEFAULT 0,
    "salt" TEXT NOT NULL DEFAULT '',
    "is_sso" SMALLINT NOT NULL DEFAULT '0',
    PRIMARY KEY ("uid")
);

CREATE TABLE IF NOT EXISTS "user_ai_memory" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "content" TEXT,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "idx_user_ai_memory_uid_content" ON "user_ai_memory" ("uid", "content");

CREATE TABLE IF NOT EXISTS "user_ai_token" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "token" VARCHAR(150) NOT NULL DEFAULT '',
    "name" VARCHAR(100) DEFAULT NULL,
    "permission" VARCHAR(20) NOT NULL DEFAULT 'write',
    "scope" VARCHAR(20) NOT NULL DEFAULT 'all',
    "allowed_items" TEXT DEFAULT NULL,
    "can_create_item" INTEGER NOT NULL DEFAULT '1',
    "can_delete_item" INTEGER NOT NULL DEFAULT '0',
    "auto_add_created_item" INTEGER NOT NULL DEFAULT '1',
    "expires_at" TIMESTAMP DEFAULT NULL,
    "created_at" TIMESTAMP DEFAULT NULL,
    "last_used_at" TIMESTAMP DEFAULT NULL,
    "is_active" INTEGER NOT NULL DEFAULT '1',
    PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "idx_is_active" ON "user_ai_token" ("is_active");
CREATE INDEX IF NOT EXISTS "idx_token" ON "user_ai_token" ("token");
CREATE INDEX IF NOT EXISTS "idx_uid" ON "user_ai_token" ("uid");

CREATE TABLE IF NOT EXISTS "user_setting" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "key_name" VARCHAR(200) NOT NULL DEFAULT '',
    "key_value" TEXT NOT NULL DEFAULT '',
    "addtime" TIMESTAMP NOT NULL DEFAULT '1970-01-01 00:00:00',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "user_token" (
    "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "uid" INTEGER NOT NULL DEFAULT '0',
    "token" VARCHAR(200) NOT NULL DEFAULT '',
    "token_expire" INTEGER NOT NULL DEFAULT '0',
    "ip" VARCHAR(200) NOT NULL DEFAULT '',
    "addtime" INTEGER NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
);

-- Hot-path indexes not present in the SQLite schema
CREATE INDEX IF NOT EXISTS "idx_item_uid" ON "item" ("uid");
CREATE INDEX IF NOT EXISTS "idx_item_domain" ON "item" ("item_domain");
CREATE INDEX IF NOT EXISTS "idx_page_item" ON "page" ("item_id");
CREATE INDEX IF NOT EXISTS "idx_catalog_item" ON "catalog" ("item_id");
CREATE INDEX IF NOT EXISTS "idx_item_member_item_uid" ON "item_member" ("item_id", "uid");
CREATE INDEX IF NOT EXISTS "idx_team_item_member_item_uid" ON "team_item_member" ("item_id", "member_uid");
CREATE INDEX IF NOT EXISTS "idx_user_username" ON "user" ("username");
CREATE INDEX IF NOT EXISTS "idx_user_token_token" ON "user_token" ("token");
CREATE INDEX IF NOT EXISTS "idx_export_log_uid_type_time" ON "export_log" ("uid", "export_type", "addtime");

-- Keep ShowDoc's non-sequential public IDs on a fresh database.
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM "page") THEN
        PERFORM setval(pg_get_serial_sequence('page', 'page_id'),
                       floor(random() * 200000000 + 100000000)::bigint, false);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "catalog") THEN
        PERFORM setval(pg_get_serial_sequence('catalog', 'cat_id'),
                       floor(random() * 100000000 + 400000000)::bigint, false);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "item") THEN
        PERFORM setval(pg_get_serial_sequence('item', 'item_id'),
                       floor(random() * 100000000 + 600000000)::bigint, false);
    END IF;
END $$;

-- First install: mark schema as current so the app does not run SQLite migrations.
INSERT INTO "options" ("option_name", "option_value") VALUES ('db_version_num', '36') ON CONFLICT ("option_name") DO UPDATE SET "option_value" = EXCLUDED."option_value";

COMMIT;

